import { useCallback, useEffect, useRef, useState } from 'preact/hooks'
import type { LoopData } from '../../../deno/types.ts'
import type { Loop } from '../../engine/ui/loop.ts'
import { isLocalId } from '../../utils/id.ts'
import { useAppStore } from '../store.ts'

export function useLoopData(loopId: string | null, currentLoop: Loop | undefined) {
  const api = useAppStore(state => state.api)
  const base = useAppStore(state => (loopId ? state.bases[loopId]?.code : undefined))
  const publicLoopsCache = useAppStore(state => state.publicLoopsCache)
  const likedLoopsCache = useAppStore(state => state.likedLoopsCache)
  const hotLoopsCache = useAppStore(state => state.hotLoopsCache)
  const bestLoopsCache = useAppStore(state => state.bestLoopsCache)
  const getPublicLoopCode = useAppStore(state => state.getPublicLoopCode)
  const setLoopBase = useAppStore(state => state.setLoopBase)
  const getCodeFile = useAppStore(state => state.getCodeFile)
  const [loopData, setLoopData] = useState<LoopData | null>(null)
  const [isLoading, setIsLoading] = useState(false)
  const setLoopLoading = useAppStore(state => state.setLoopLoading)
  const upsertServerLoopCache = useAppStore(state => state.upsertServerLoopCache)
  const didFetchKeyRef = useRef<string | null>(null)
  const loopLoadingReqRef = useRef(0)

  const withLoading = useCallback((fn: () => Promise<void>) => {
    setIsLoading(true)
    fn().finally(() => setIsLoading(false))
  }, [])

  useEffect(() => {
    loopLoadingReqRef.current++
    if (loopId == null) {
      didFetchKeyRef.current = null
      setLoopData(null)
      setIsLoading(false)
      setLoopLoading(false)
      return
    }
    if (isLocalId(loopId)) {
      didFetchKeyRef.current = `${loopId}:local`
      setLoopData(null)
      setIsLoading(false)
      setLoopLoading(false)
      return
    }

    const isPublicLoop = publicLoopsCache.some(l => l.id === loopId)
      || likedLoopsCache.some(l => l.id === loopId)
      || hotLoopsCache.some(l => l.id === loopId)
      || bestLoopsCache.some(l => l.id === loopId)
    const fetchKey = `${loopId}:${isPublicLoop ? 'public' : 'private'}`
    if (isPublicLoop) {
      const meta = publicLoopsCache.find(l => l.id === loopId)
        ?? likedLoopsCache.find(l => l.id === loopId)
        ?? hotLoopsCache.find(l => l.id === loopId)
        ?? bestLoopsCache.find(l => l.id === loopId)
      const needsMeta = meta?.artistId === 'unknown'
      const hasCode = base != null || (typeof currentLoop?.data.code === 'string')

      if (hasCode) {
        if (didFetchKeyRef.current !== fetchKey) {
          didFetchKeyRef.current = fetchKey
          if (needsMeta) void getPublicLoopCode(loopId)
        }
        setLoopData(null)
        setIsLoading(false)
        return
      }
      if (didFetchKeyRef.current === fetchKey) return
      didFetchKeyRef.current = fetchKey

      const fetch = async () => {
        const code = await getPublicLoopCode(loopId)
        const state = useAppStore.getState()
        const ts = state.publicLoopsCache.find(l => l.id === loopId)?.timestamp
          ?? state.likedLoopsCache.find(l => l.id === loopId)?.timestamp
          ?? state.hotLoopsCache.find(l => l.id === loopId)?.timestamp
          ?? state.bestLoopsCache.find(l => l.id === loopId)?.timestamp
          ?? currentLoop?.data.timestamp
        setLoopBase(loopId, code, ts)
        const codeFile = getCodeFile(loopId, code)
        if (codeFile.value.length === 0 && code.length > 0) {
          codeFile.value = code
        }
      }

      withLoading(fetch)
      return
    }

    const hasCode = base != null || (typeof currentLoop?.data.code === 'string')
    if (hasCode) {
      didFetchKeyRef.current = fetchKey
      setLoopData(null)
      setIsLoading(false)
      return
    }
    if (didFetchKeyRef.current === fetchKey) return
    didFetchKeyRef.current = fetchKey

    const fetch = async () => {
      const data = await api.fetchLoopData(loopId)
      setLoopData(data)
      upsertServerLoopCache(data)
    }

    withLoading(fetch)
  }, [
    api,
    base,
    currentLoop?.data.code,
    currentLoop?.data.timestamp,
    getCodeFile,
    getPublicLoopCode,
    hotLoopsCache,
    bestLoopsCache,
    likedLoopsCache,
    loopId,
    publicLoopsCache,
    setLoopBase,
    upsertServerLoopCache,
    withLoading,
  ])

  useEffect(() => {
    const req = ++loopLoadingReqRef.current
    if (isLoading) {
      setLoopLoading(true)
      return
    }
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (loopLoadingReqRef.current !== req) return
        setLoopLoading(false)
      })
    })
  }, [isLoading, setLoopLoading])

  const best = loopId && loopData?.id === loopId
    ? loopData
    : (currentLoop?.data ?? null)

  return { isLoading, loopData: best }
}
